"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5088],{60001:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"GrabHook","desc":"Tool script for the Grabhook item. On activation it spherecasts from the\\nhandle attachment toward the mouse cursor to find aimed junk, fires\\n`Signals.TryClaimJunk` (handled by `JunkController`), then plays the\\noutgoing beam and retraction animation via `GrabHookVisuals.AnimateProjectile`\\nbefore firing `Signals.TryFinalizeJunk` on retract completion. The looping\\nsound is scheduled around the animation timeline. A\\nper-frame force-field highlight tracks the currently aimed junk with a short\\ngrace period to prevent flicker. Equip and unequip toggle aim-mode camera\\nvia `Signals.RequestShootingCamera`.","realm":["Client"],"source":{"line":14,"path":"src/StarterPack/Grabhook/GrabHook.client.luau"}}')}}]);